from pathlib import Path
R=Path('kitaplar/lise-a2/bir-hikayem-var');answers={}
def add(n,title,items,note=None):
 answers[str(n)]={'sections':[{'title':title,'items':items}]}
 if note:answers[str(n)]['note']=note
add(1,'Hazırlık · Örnek cevaplar',['Masal ve hikâye kahramanları görüyorum. Keloğlan gibi tanıdığım karakterleri söyleyebilirim.','Bu ünitede masal anlatmayı, geçmiş olayları aktarmayı, hayat hikâyesi yazmayı ve karakter özelliklerini anlatmayı çalışacağız.'],'Görsel yorumları ve öğrencinin bildiği kahramanlar kişiseldir.')
add(2,'Hızır ve İlyas · Metne göre',['İskender ölümsüzlük suyunu arıyor.','Bu sudan içen kişinin hastalanmayacağı ve ebedî yaşayacağı anlatılıyor.','Hızır ve İlyas Karanlıklar Ülkesi’ne gidiyor. Bir çeşmenin başında dinleniyorlar.','Melek, onlardan ömürleri boyunca karadaki ve denizdeki insanlara yardım etmelerini istiyor.'],'Bunlar hikâyenin içeriğidir; gerçek hayata ilişkin bir sağlık iddiası değildir. S.054 özgün kaydı bulunamadı; yazılı metin okunabilir.')
add(3,'Hikâyenin devamı',['Kurutulmuş balık, çeşmeden sıçrayan suyla canlanıp suya atlıyor.','Hızır ve İlyas bunun ölümsüzlük suyu olduğunu anlıyor ve sudan içiyor.','Hızır karadaki, İlyas denizdeki insanlara yardım ediyor. Hikâyeye göre mayısın altıncı günü buluşuyorlar.'])
add(4,'Deyimler ve okuduğunu anlama',['4. etkinlik: 1-d, 2-a, 3-b, 4-ç, 5-e, 6-f, 7-c.','5-a: İskender, Hızır, İlyas, bilge kişi ve melek. Mekânlar: dağlar, denizler, çöller ve Karanlıklar Ülkesi’ndeki çeşme.','5-b: 1-c, 2-g, 3-f, 4-ç, 5-a, 6-e, 7-d, 8-b, 9-h.','6-a: Numaralı akışta 2-D, 4-C, 6-A, 7-B, 9-E. Başlangıçtaki 1. kutuda Ç zaten verilmiştir.'],'5-b’de Bahar Bayramı ifadesi kullanılıyor; metinde buluşma günü mayısın altıncı günü olarak belirtiliyor.')
add(5,'Okuma ve söz varlığı',['7-a: c — Hızır ve İlyas’ın ölümsüzlük suyunu araması.','7-b: İskender ölümsüz olmak istiyor. Hızır ve İlyas onun emriyle aramaya çıkıyor. Meleğin şartı insanlara yardım etmeleridir.','Örnek sonuç: İnsanlara yardım etmek değerlidir. Farklı ve metne dayalı yorumlar kabul edilebilir.','Duygu ifadeleri: Aklım çıktı → korku; Yaşasın → sevinç; Gerçekten mi → şaşkınlık; Ben sana… demedim mi → kızgınlık; Hiç sormayın → üzüntü/sıkıntı; Ya işleri bitiremezsem → endişe.'],'Görsellerin harf eşleştirmesinde yüz ifadesini ve hareketleri birlikte değerlendirin.')
add(6,'Bakla Ağacı · Dinleme',['S.055 özgün dinleme kaydı bu depoda bulunamadı. Görsel sırası, zaman, mekân ve karakter ayrıntıları kesin cevap olarak tahmin edilmedi.','Dinleme öncesi sorular görsellere bakılarak yorumlanabilir.'])
add(7,'Diyalog · Metne dayalı cevaplar',['6-a: Keçiler, komşu kadının kaba sözlerine alaylı bir teşekkürle karşılık veriyor.','6-b: Komşu kadın onların sözlerini gerçek bir teşekkür ve hediye vaadi gibi anlayabilir.','6-c: Yazılı diyalogda birer bez torba verdikleri söyleniyor; torbaların içeriği bu paragrafta açıklanmıyor.','7. etkinlikte nezaket, paylaşma ve saygı üzerine metne dayalı yorumlar yapılabilir.'],'5. etkinlikteki dinleme ayrıntıları S.055 olmadan kesinleştirilmedi.')
add(8,'İma, ikilemeler ve şiir',['1-a: Cümlelerde söylenenin tersini kasteden alaylı ifadeler var: uzun bekleme, kötü yapılan iş, övünme ve sağlıksız beslenme.','2-a: 1-a, 2-b, 3-ç, 4-c, 5-d.','Örnek paragraf: Yaşlı kadın yavaş yavaş odaya girdi. Sandığın içindeki gümüşler ışıl ışıl parlıyordu. Sandığın dışı da pırıl pırıldı.','Şiirde sıkıntıların geçici olduğu ve sabır vurgulanır.'],'Paragraf ve şiir yorumu için farklı tutarlı cevaplar kabul edilir.')
add(9,'Ağustos Böceği ve Karınca · Örnek anlatım',['Görsellere göre yazın müzikle vakit geçiren Ağustos Böceği ve yiyecek biriktiren Karınca anlatılıyor.','Örnek başlık: Ağustos Böceği ile Karınca.','Yardım etme konusundaki görüşünüzü gerekçelendirin. Canlandırmada yaz ve kış arasındaki farkı gösterin.'],'Sayfada ses kodu belirtilmiyor. Bu özet görsellerden oluşturulmuş örnektir; bulunmayan bir ses kaydının dökümü değildir.')
add(10,'Keloğlan · Video ve yazma',['V.010 özgün videosu bulunamadı. Olay sırası, mekânlar ve kıyafet ayrıntıları tahmin edilmedi.','Videoyu izledikten sonra Keloğlan, marangoz, bey ve hanımın özelliklerini tabloya yazın.','Olayları başlama, gelişme ve sonuç sırasıyla yeniden anlatın.'])
add(11,'Benim Hikâyem · Okuma',['Anlatıcı Mevlânâ Celâleddîn-i Rûmî’dir.','Metne göre 1207’de Belh’te doğmuş; 1212–1213’te ailesiyle Belh’ten ayrılıp Nişabur’a göç etmiş.','Metne göre 1222’de Karaman’a gelmiş, Gevher Hatun ile evlenmiş ve sonra Konya’ya göç etmiş.','En ünlü eseri Mesnevî, dostu Şems-i Tebrizî olarak veriliyor.'],'Kaynak metinde ölüm tarihi “12 Ocak 1273” yazılmıştır. Tarih bilgisi kaynak hatası olabileceğinden cevaplarda yalnızca metinde de geçen 1273 yılı kullanılmıştır.')
add(12,'Mevlânâ · Cevaplar',['4. etkinlik: B.','5. etkinlik: 1-D; 2-Y → Belh’te doğmuştur; 3-Y → Karaman’da evlenmiştir; 4-D; 5-D (metinde iki çocuk adı veriliyor); 6-Y → Konya’da ölmüştür; 7-D (metnin anlatımına göre).','6. etkinlik: 1207 doğumu; 1212–1213 Belh’ten ayrılıp Nişabur’a göçü; 1222 Karaman’a gelişi; 1273 ölümü.','7. etkinlikte kendi hayatınıza ait tarihleri kullanın.'],'Cevaplar verilen okuma metnine göredir. Kaynakta verilen çocuk sayısı tarihsel bakımdan kapsamlı biyografi bilgisi gibi sunulmamalıdır.')
add(13,'Sait Faik · Biyografi ve deyimler',['1-a: Dört kutunun yukarıdan aşağı sırası 3, 1, 4, 2.','Not: Yönerge 1–5 diyor; sayfada dört biyografi kutusu var. Olmayan beşinci kutu için cevap eklenmedi.','1-b: 1-b (doğmak), 2-c (yazmak), 3-a (ölmek).','Örnek biyografide doğum, eğitim, eserler ve önemli olaylar zaman sırasıyla anlatılabilir.'])
add(14,'Ölümsüzlük Ağacını Arayan Adam · Dinleme',['S.057 özgün dinleme kaydı bulunamadı; görsel ve duygu sıralamaları tahmin edilmedi.','Masalın konusu sonraki sayfada yer alan yazılı cümlelerden incelenebilir.'])
add(15,'Yazılı cümlelere göre olay sırası',['6-a: Yukarıdan aşağı numaralar 1, 5, 7, 3, 6, 9, 4, 11, 8, 10, 2.','7-b: Bilge kişi, ölümsüzlük ağacını bilgi ağacı olarak tanımlıyor; meyvesinin bilgi olduğunu söylüyor.','7-c: Gerçek değerin bilgide ve bilgili insanlarda olduğu vurgulanıyor.'],'Sıralama, sayfadaki yazılı cümlelerin mantıksal sırasına göre hazırlanmıştır; S.057 kaydıyla karşılaştırılamadı.')
add(16,'Karakter özellikleri ve masal anlatma',['1-a: 1-a, 2-b, 3-m, 4-ı, 5-d, 6-i, 7-c, 8-f, 9-k, 10-n, 11-e, 12-g, 13-l, 14-o.','1-b: Genellikle olumlu: cesur, cömert, neşeli, dürüst, iyimser, sakin. Genellikle olumsuz: yalancı, cimri, kıskanç, bencil, kötümser, telaşlı, kibirli, korkak.','Masal anlatırken zaman, mekân, kahraman, olay ve sonucu belirtin.'],'Özelliklerin değerlendirilmesi bağlama göre tartışılabilir. Kaynakta “gözlerine inanamak” yazımı var; doğru kalıp “gözlerine inanamamak”tır.')
add(17,'Yazma · Örnek masal planı',['Mekân: Küçük bir köy. Kahramanlar: Bir çocuk, bir nine ve bir tilki. Zaman: Eski zamanlarda.','Örnek başlangıç: Bir varmış bir yokmuş. Küçük bir köyde meraklı bir çocuk yaşarmış. Bir gün kaybolan keçiyi bulmak için yola çıkmış.','Devamında sorunu, çözümü ve kahramanın öğrendiği dersi yazın.'],'Bu açık uçlu etkinlikte tek bir doğru masal yoktur.')
add(18,'Hayat hikâyesi · Yazma kontrolü',['Giriş: Adı, ailesi, memleketi, doğum yeri ve tarihi.','Gelişme: Eğitim, evlilik, çocuklar, yetenekler, hobiler, yarışmalar ve başarılar.','Sonuç: Ölüm tarihi veya gelecek planları; kişinin yaşam durumuna uygun olanı seçin.','Dünyaya gelmek, dünya evine girmek, hayata gözlerini yummak deyimlerini anlamlarına uygun kullanın.'])
add(19,'Adile Naşit · Video',['V.011 özgün videosu bulunamadı. Görsel sıralaması ve videoya bağlı seçenekler tahmin edilmedi.','Videoyu izledikten sonra kahraman, mekân, neden ve olay sırası sorularını cevaplayın.'])
add(20,'Bir Mekân Bir Efsane · Proje',['Ülkenizde bir mekân seçin ve efsanesini araştırın.','Aile büyüklerinden veya kaynaklardan öğrendiklerinizi not edin.','Bir video planlayın, hikâyeyi anlatın, fotoğrafları ekleyin ve sınıfta sunun.','Sunumu anlatımın açıklığı, olay sırası ve kullanılan görseller bakımından değerlendirin.'],'Bir hafta içinde yapılabilecek açık uçlu proje örneğidir.')
(R/'answers.json').write_text(json.dumps(answers,ensure_ascii=False,separators=(',',':')))
