h=re.sub(r'<nav class="unit-navigation" aria-label="Üniteler arasında geçiş">.*?</nav>','<nav class="unit-navigation" aria-label="Üniteler arasında geçiş"><a class="unit-nav-button" href="../spor-ve-saglik/">← Bir Önceki Ünite</a><button class="unit-nav-button" disabled title="10. ünite henüz hazırlanmadı">Bir Sonraki Ünite →</button></nav>',h,count=1)
